_ASCII_DIGITS = frozenset("0123456789")


def parse_count(text):
    """Parse a count made of nonempty ASCII decimal digits.

    Accepts "0" and leading zeroes. Rejects signs, whitespace, floats,
    underscores, and non-ASCII digits, all of which int() would accept.
    """
    if not isinstance(text, str) or not text or not set(text) <= _ASCII_DIGITS:
        raise ValueError(f"invalid count: {text!r}")
    return int(text)

